<script setup lang="ts">
import {ref} from 'vue';import type {RequestFn} from './media';
const props=defineProps<{request:RequestFn,target:Record<string,any>,kind:'customers'|'administrators'}>();const emit=defineEmits<{close:[],changed:[message:string]}>();const busy=ref(false),error=ref(''),confirmed=ref(false);
async function submit(){if(!confirmed.value||busy.value)return;busy.value=true;error.value='';try{const restoring=!!props.target.deleted_at;const r=await props.request('admin/'+props.kind+(restoring?'/restore':''),restoring?'POST':'DELETE',{id:props.target.id,version:props.target.admin_version,confirmed:true});emit('changed',r.message)}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop"><form class="modal" role="dialog" aria-modal="true" aria-label="账户删除与恢复" @submit.prevent="submit"><div class="section-head"><h2>{{target.deleted_at?'恢复':'删除'}}{{kind==='administrators'?'副管理员':'用户'}}</h2><button type="button" :disabled="busy" @click="emit('close')" aria-label="关闭">×</button></div><p><strong>{{target.name}}</strong> · {{target.email}}</p><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="target.deleted_at" class="alert">恢复后仍为停用状态。请核对资料与权限，再手动启用；不会自动重新开通代理服务。</p><p v-else class="alert">删除后立即注销登录并移出正常列表。{{kind==='administrators'?'关联的机器人核款权限立即失效。':'全部订单的代理撤权任务会排队执行；请查看后台任务确认节点已同步。'}}订单、付款与操作记录保留，账户可从“已删除”列表恢复。</p><label class="multi"><input type="checkbox" v-model="confirmed" :disabled="busy">我已核对账户，确认{{target.deleted_at?'恢复为停用状态':'删除此账户'}}</label><div class="modal-actions"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!confirmed">{{busy?'处理中…':target.deleted_at?'确认恢复':'确认删除'}}</button></div></form></div></template>
